Definition term_ok (c : CC.cutpoint) (cells : list kentry) (l : PSO.pv) : bool :=
  (negb (PSO.has_bufbyte (CC.cp_F c)) || PSO.has cells (KWord (SA (APC.eadd (PSO.v_size l) (PSO.v_bptr l)) 0) 1 (ELit 0)))%bool.
Definition p213_ok (c : CC.cutpoint) (cells : list kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$c;R+0$cells;R!1+1+2!2'3!2'4#1!3,5!2,6'7!1,8|755;}1!1,9,:!1';!3'<'=!1'>!4,?!2+@+A+B+A!4,?+A+B'7!1,8|748;!1,9!1,8|40;!1'C#2").
